-- Invocations 5 à 8 : voyage, repas, maison, angoisse et malheur
with it as (insert into public.content_items (slug, kind, section, locale, position)
            values ($x$adhkar-voyage$x$, 'lesson', 'adhkar', 'fr', 5) returning id),
rv as (insert into public.content_revisions (item_id, number, title, summary, body, ai_assisted, author_name)
       select id, 1, $x$Le voyage$x$, $x$Les invocations du départ, du retour et des haltes en voyage.$x$, $x$Au départ d'un voyage, le Prophète ﷺ disait trois fois « Allāhu akbar » en s'installant sur sa monture, puis il prononçait l'invocation du voyage. Son début reprend les versets 13 et 14 de la sourate az-Zukhruf (43). Au retour, il redisait la même invocation en y ajoutant quelques mots. Jābir rapporte aussi que les Compagnons disaient « Allāhu akbar » en montant et « Subḥāna llāh » en descendant (al-Bukhārī n° 2993).$x$, true, $x$Claude (assistant IA)$x$ from it returning id, item_id),
r as (insert into public.content_references (revision_id, kind, surah, ayah_from, ayah_to, collection, edition, hadith_number, grade, graded_by, source_title, url, note)
