  (1, $x$hadith$x$::public.reference_kind, null::int, null::int, null::int, $x$Ṣaḥīḥ Muslim$x$, $x$Numérotation de sunnah.com$x$, $x$1342$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique de Muslim$x$, $x$Ṣaḥīḥ Muslim$x$, $x$https://sunnah.com/muslim:1342$x$, $x$D'après ʿAbd Allāh ibn ʿUmar.$x$),
  (2, $x$quran$x$::public.reference_kind, 43::int, 13::int, 14::int, null, null, null, null, null, null, null, null),
  (3, $x$hadith$x$::public.reference_kind, null::int, null::int, null::int, $x$Ṣaḥīḥ Muslim$x$, $x$Numérotation de sunnah.com$x$, $x$2708a$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique de Muslim$x$, $x$Ṣaḥīḥ Muslim$x$, $x$https://sunnah.com/muslim:2708a$x$, $x$D'après Khawla bint Ḥakīm.$x$),
  (4, $x$hadith$x$::public.reference_kind, null::int, null::int, null::int, $x$Ṣaḥīḥ al-Bukhārī$x$, $x$Numérotation de sunnah.com$x$, $x$2993$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique d'al-Bukhārī$x$, $x$Ṣaḥīḥ al-Bukhārī$x$, $x$https://sunnah.com/bukhari:2993$x$, $x$D'après Jābir ibn ʿAbd Allāh.$x$)) v(k, kind, surah, ayah_from, ayah_to, collection, edition, hadith_number, grade, graded_by, source_title, url, note) order by v.k returning 1),
a as (insert into public.content_adhkar (revision_id, title, arabic, transliteration, meaning, repeat_count, when_to_say, virtue, collection, hadith_number, grade, graded_by, url, note)
      select rv.id, v.title, v.arabic, v.transliteration, v.meaning, v.repeat_count, v.when_to_say, v.virtue, v.collection, v.hadith_number, v.grade, v.graded_by, v.url, v.note from rv, (values
  (1, $x$L'invocation du voyage$x$, $x$سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى وَمِنَ الْعَمَلِ مَا تَرْضَى اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الأَهْلِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمَنْظَرِ وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالأَهْلِ$x$, $x$Subḥāna lladhī sakhkhara lanā hādhā wa mā kunnā lahu muqrinīn, wa innā ilā rabbinā la-munqalibūn. Allāhumma innā nas’aluka fī safarinā hādha l-birra wa t-taqwā, wa mina l-ʿamali mā tarḍā. Allāhumma hawwin ʿalaynā safaranā hādhā wa-ṭwi ʿannā buʿdah. Allāhumma anta ṣ-ṣāḥibu fi s-safar, wa l-khalīfatu fi l-ahl. Allāhumma innī aʿūdhu bika min waʿthā’i s-safar, wa ka’ābati l-manẓar, wa sū’i l-munqalabi fi l-māli wa l-ahl.$x$, $x$« Gloire à Celui qui a mis ceci à notre service alors que nous n'étions pas capables de le maîtriser, et c'est vers notre Seigneur que nous retournerons. Ô Allah, nous Te demandons, dans ce voyage, la bonté et la piété, et des œuvres qui Te plaisent. Ô Allah, facilite-nous ce voyage et raccourcis-nous sa distance. Ô Allah, Tu es le Compagnon dans le voyage et Celui qui veille sur la famille. Ô Allah, je cherche refuge auprès de Toi contre les fatigues du voyage, contre tout spectacle attristant et contre un mauvais retour, dans les biens et dans la famille. »$x$, 1::smallint, $x$En s'installant sur sa monture au départ d'un voyage, après avoir dit trois fois « Allāhu akbar »$x$, null, $x$Ṣaḥīḥ Muslim$x$, $x$1342$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique de Muslim$x$, $x$https://sunnah.com/muslim:1342$x$, $x$D'après ʿAbd Allāh ibn ʿUmar.$x$),
  (2, $x$Nous revenons, repentants$x$, $x$آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ$x$, $x$Āyibūna tā’ibūna ʿābidūna li-rabbinā ḥāmidūn.$x$, $x$« Nous revenons, repentants, adorant notre Seigneur et Le louant. »$x$, 1::smallint, $x$Au retour du voyage : on redit l'invocation du départ et on y ajoute ces paroles$x$, null, $x$Ṣaḥīḥ Muslim$x$, $x$1342$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique de Muslim$x$, $x$https://sunnah.com/muslim:1342$x$, $x$D'après ʿAbd Allāh ibn ʿUmar, dans le même hadith que l'invocation du départ.$x$),
  (3, $x$En faisant halte$x$, $x$أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ$x$, $x$Aʿūdhu bi-kalimāti llāhi t-tāmmāti min sharri mā khalaq.$x$, $x$« Je cherche refuge dans les paroles parfaites d'Allah contre le mal de ce qu'Il a créé. »$x$, 1::smallint, $x$En faisant halte dans un lieu$x$, $x$Rien ne lui nuit jusqu'à ce qu'il quitte ce lieu.$x$, $x$Ṣaḥīḥ Muslim$x$, $x$2708a$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique de Muslim$x$, $x$https://sunnah.com/muslim:2708a$x$, $x$D'après Khawla bint Ḥakīm.$x$)) v(k, title, arabic, transliteration, meaning, repeat_count, when_to_say, virtue, collection, hadith_number, grade, graded_by, url, note) order by v.k returning arabic)
