       rv.id as revision, (select bool_and(md5(arabic) = any(array['51879a14f499c996418c0a0be823f562', 'ee85053f68c17f8294b8fb3d10c268d7', 'efe26c0a7a7aa3d65e8a614bc75333f6'])) and count(*) = 3 from a) as arabe_ok,
