rv as (insert into public.content_revisions (item_id, number, title, summary, body, ai_assisted, author_name)
       select id, 1, $x$Le repas$x$, $x$Ce que l’on dit avant et après avoir mangé.$x$, $x$Le Prophète ﷺ a dit à ʿUmar ibn Abī Salama, qui était alors un enfant : mentionne le nom d'Allah, mange de ta main droite et mange de ce qui est devant toi (al-Bukhārī n° 5376). Mentionner le nom d'Allah avant de manger, c'est dire « Bismillāh ». Celui qui a oublié de le dire au début du repas le dit dès qu'il s'en souvient, avec la formule ci-dessous. À la fin du repas, on loue Allah.$x$, true, $x$Claude (assistant IA)$x$ from it returning id, item_id),
