      select rv.id, v.title, v.arabic, v.transliteration, v.meaning, v.repeat_count, v.when_to_say, v.virtue, v.collection, v.hadith_number, v.grade, v.graded_by, v.url, v.note from rv, (values
  (1, $x$Au nom d’Allah, au début et à la fin$x$, $x$بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ$x$, $x$Bismi llāhi awwalahu wa ākhirah.$x$, $x$« Au nom d'Allah, au début et à la fin. »$x$, 1::smallint, $x$Si l'on a oublié de dire « Bismillāh » au début du repas$x$, null, $x$Sunan Abī Dāwūd$x$, $x$3767$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Al-Albānī (jugement affiché sur sunnah.com)$x$, $x$https://sunnah.com/abudawud:3767$x$, $x$D'après ʿĀʾisha. Shuʿayb al-Arnaʾūṭ l'a jugé authentique par ses autres voies (ṣaḥīḥ li-ghayrihi).$x$),
  (2, $x$Louange abondante, bonne et bénie$x$, $x$الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ، وَلاَ مُوَدَّعٍ وَلاَ مُسْتَغْنًى عَنْهُ، رَبَّنَا$x$, $x$Al-ḥamdu li-llāhi kathīran ṭayyiban mubārakan fīh, ghayra makfiyyin wa lā muwaddaʿin wa lā mustaghnan ʿanhu, rabbanā.$x$, $x$« Louange à Allah, une louange abondante, bonne et bénie, louange qui n'est jamais suffisante, que l'on ne délaisse pas et dont on ne peut se passer, ô notre Seigneur. »$x$, 1::smallint, $x$À la fin du repas$x$, null, $x$Ṣaḥīḥ al-Bukhārī$x$, $x$5458$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique d'al-Bukhārī$x$, $x$https://sunnah.com/bukhari:5458$x$, $x$D'après Abū Umāma. Les commentateurs expliquent de plusieurs façons le sens exact de certains mots de cette invocation.$x$)) v(k, title, arabic, transliteration, meaning, repeat_count, when_to_say, virtue, collection, hadith_number, grade, graded_by, url, note) order by v.k returning arabic)
