rv as (insert into public.content_revisions (item_id, number, title, summary, body, ai_assisted, author_name)
       select id, 1, $x$Entrer et sortir de chez soi$x$, $x$Mentionner Allah en entrant chez soi, et les invocations de la sortie.$x$, $x$Le Prophète ﷺ a enseigné que celui qui mentionne Allah en entrant chez lui et au moment de son repas empêche le diable d'y passer la nuit et d'y manger (Muslim n° 2018a). Pour la sortie, deux invocations sont rapportées ci-dessous. Une formule précise pour l'entrée, rapportée par Abū Dāwūd (n° 5096), a été jugée faible par al-Albānī : elle n'est donc pas présentée ici comme une invocation à dire.$x$, true, $x$Claude (assistant IA)$x$ from it returning id, item_id),
