  (2, $x$hadith$x$::public.reference_kind, null::int, null::int, null::int, $x$Sunan Abī Dāwūd$x$, $x$Numérotation de sunnah.com$x$, $x$5095$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Al-Albānī (jugement affiché sur sunnah.com)$x$, $x$Sunan Abī Dāwūd$x$, $x$https://sunnah.com/abudawud:5095$x$, $x$D'après Anas ibn Mālik.$x$),
  (3, $x$hadith$x$::public.reference_kind, null::int, null::int, null::int, $x$Sunan Abī Dāwūd$x$, $x$Numérotation de sunnah.com$x$, $x$5094$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Al-Albānī (jugement affiché sur sunnah.com)$x$, $x$Sunan Abī Dāwūd$x$, $x$https://sunnah.com/abudawud:5094$x$, $x$D'après Umm Salama.$x$),
  (4, $x$hadith$x$::public.reference_kind, null::int, null::int, null::int, $x$Sunan Abī Dāwūd$x$, $x$Numérotation de sunnah.com$x$, $x$5096$x$, $x$Faible (ḍaʿīf)$x$, $x$Al-Albānī (jugement affiché sur sunnah.com)$x$, $x$Sunan Abī Dāwūd$x$, $x$https://sunnah.com/abudawud:5096$x$, $x$Cité seulement pour signaler sa faiblesse.$x$)) v(k, kind, surah, ayah_from, ayah_to, collection, edition, hadith_number, grade, graded_by, source_title, url, note) order by v.k returning 1),
a as (insert into public.content_adhkar (revision_id, title, arabic, transliteration, meaning, repeat_count, when_to_say, virtue, collection, hadith_number, grade, graded_by, url, note)
      select rv.id, v.title, v.arabic, v.transliteration, v.meaning, v.repeat_count, v.when_to_say, v.virtue, v.collection, v.hadith_number, v.grade, v.graded_by, v.url, v.note from rv, (values
  (1, $x$Au nom d’Allah, je place ma confiance en Allah$x$, $x$بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ$x$, $x$Bismi llāh, tawakkaltu ʿala llāh, lā ḥawla wa lā quwwata illā bi-llāh.$x$, $x$« Au nom d'Allah, je place ma confiance en Allah ; il n'y a de force ni de puissance qu'en Allah. »$x$, 1::smallint, $x$En sortant de chez soi$x$, $x$On lui dit alors : tu es guidé, tu es suffi et tu es protégé, et les diables s'écartent de lui.$x$, $x$Sunan Abī Dāwūd$x$, $x$5095$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Al-Albānī (jugement affiché sur sunnah.com)$x$, $x$https://sunnah.com/abudawud:5095$x$, $x$D'après Anas ibn Mālik.$x$),
  (2, $x$Contre l’égarement et l’injustice$x$, $x$اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ أَوْ أَزِلَّ أَوْ أُزَلَّ أَوْ أَظْلِمَ أَوْ أُظْلَمَ أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَىَّ$x$, $x$Allāhumma innī aʿūdhu bika an aḍilla aw uḍall, aw azilla aw uzall, aw aẓlima aw uẓlam, aw ajhala aw yujhala ʿalayy.$x$, $x$« Ô Allah, je cherche refuge auprès de Toi contre le fait de m'égarer ou d'être égaré, de faire un faux pas ou d'y être poussé, d'être injuste ou de subir l'injustice, d'agir en ignorant ou que l'on agisse envers moi en ignorant. »$x$, 1::smallint, $x$En sortant de chez soi ; le Prophète ﷺ levait alors le regard vers le ciel$x$, null, $x$Sunan Abī Dāwūd$x$, $x$5094$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Al-Albānī (jugement affiché sur sunnah.com)$x$, $x$https://sunnah.com/abudawud:5094$x$, $x$D'après Umm Salama. Shuʿayb al-Arnaʾūṭ l'a jugé ḥasan ṣaḥīḥ ; Zubayr ʿAlī Zaʾī l'a jugé faible (jugements affichés sur sunnah.com).$x$)) v(k, title, arabic, transliteration, meaning, repeat_count, when_to_say, virtue, collection, hadith_number, grade, graded_by, url, note) order by v.k returning arabic)
