with it as (insert into public.content_items (slug, kind, section, locale, position)
            values ($x$adhkar-epreuves$x$, 'lesson', 'adhkar', 'fr', 8) returning id),
rv as (insert into public.content_revisions (item_id, number, title, summary, body, ai_assisted, author_name)
       select id, 1, $x$L’angoisse et le malheur$x$, $x$Les invocations de la détresse et celle que l’on dit quand un malheur frappe.$x$, $x$Le Prophète ﷺ a enseigné plusieurs invocations pour les moments d'angoisse et de détresse, et une autre pour le moment où un malheur frappe. Cette dernière commence par les paroles mentionnées dans le verset 156 de la sourate al-Baqara (2), que le hadith appelle « ce qu'Allah lui a ordonné ».$x$, true, $x$Claude (assistant IA)$x$ from it returning id, item_id),
r as (insert into public.content_references (revision_id, kind, surah, ayah_from, ayah_to, collection, edition, hadith_number, grade, graded_by, source_title, url, note)
      select rv.id, v.kind, v.surah, v.ayah_from, v.ayah_to, v.collection, v.edition, v.hadith_number, v.grade, v.graded_by, v.source_title, v.url, v.note from rv, (values
  (1, $x$hadith$x$::public.reference_kind, null::int, null::int, null::int, $x$Ṣaḥīḥ al-Bukhārī$x$, $x$Numérotation de sunnah.com$x$, $x$6346$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique d'al-Bukhārī$x$, $x$Ṣaḥīḥ al-Bukhārī$x$, $x$https://sunnah.com/bukhari:6346$x$, $x$D'après Ibn ʿAbbās.$x$),
  (2, $x$hadith$x$::public.reference_kind, null::int, null::int, null::int, $x$Sunan Abī Dāwūd$x$, $x$Numérotation de sunnah.com$x$, $x$1525$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Al-Albānī (jugement affiché sur sunnah.com)$x$, $x$Sunan Abī Dāwūd$x$, $x$https://sunnah.com/abudawud:1525$x$, $x$D'après Asmāʾ bint ʿUmays.$x$),
  (3, $x$hadith$x$::public.reference_kind, null::int, null::int, null::int, $x$Ṣaḥīḥ Muslim$x$, $x$Numérotation de sunnah.com$x$, $x$918a$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique de Muslim$x$, $x$Ṣaḥīḥ Muslim$x$, $x$https://sunnah.com/muslim:918a$x$, $x$D'après Umm Salama.$x$),
  (4, $x$quran$x$::public.reference_kind, 2::int, 156::int, 156::int, null, null, null, null, null, null, null, null),
  (5, $x$hadith$x$::public.reference_kind, null::int, null::int, null::int, $x$Sunan Abī Dāwūd$x$, $x$Numérotation de sunnah.com$x$, $x$5090$x$, $x$Chaîne bonne (ḥasan al-isnād)$x$, $x$Al-Albānī (jugement affiché sur sunnah.com)$x$, $x$Sunan Abī Dāwūd$x$, $x$https://sunnah.com/abudawud:5090$x$, $x$D'après Abū Bakra. Zubayr ʿAlī Zaʾī l'a jugé faible.$x$)) v(k, kind, surah, ayah_from, ayah_to, collection, edition, hadith_number, grade, graded_by, source_title, url, note) order by v.k returning 1),
a as (insert into public.content_adhkar (revision_id, title, arabic, transliteration, meaning, repeat_count, when_to_say, virtue, collection, hadith_number, grade, graded_by, url, note)
      select rv.id, v.title, v.arabic, v.transliteration, v.meaning, v.repeat_count, v.when_to_say, v.virtue, v.collection, v.hadith_number, v.grade, v.graded_by, v.url, v.note from rv, (values
  (1, $x$Allah, l’Immense, le Longanime$x$, $x$لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ، وَرَبُّ الأَرْضِ، وَرَبُّ الْعَرْشِ الْكَرِيمِ$x$, $x$Lā ilāha illa llāhu l-ʿaẓīmu l-ḥalīm, lā ilāha illa llāhu rabbu l-ʿarshi l-ʿaẓīm, lā ilāha illa llāhu rabbu s-samāwāti wa rabbu l-arḍi wa rabbu l-ʿarshi l-karīm.$x$, $x$« Nul ne mérite d'être adoré si ce n'est Allah, l'Immense, le Longanime ; nul ne mérite d'être adoré si ce n'est Allah, le Seigneur du Trône immense ; nul ne mérite d'être adoré si ce n'est Allah, le Seigneur des cieux, le Seigneur de la terre et le Seigneur du noble Trône. »$x$, 1::smallint, $x$Dans l'angoisse et la détresse$x$, null, $x$Ṣaḥīḥ al-Bukhārī$x$, $x$6346$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique d'al-Bukhārī$x$, $x$https://sunnah.com/bukhari:6346$x$, $x$D'après Ibn ʿAbbās.$x$),
  (2, $x$Allah est mon Seigneur$x$, $x$اللَّهُ اللَّهُ رَبِّي لاَ أُشْرِكُ بِهِ شَيْئًا$x$, $x$Allāhu Allāhu rabbī, lā ushriku bihi shay’ā.$x$, $x$« Allah, Allah est mon Seigneur, je ne Lui associe rien. »$x$, 1::smallint, $x$Dans l'angoisse ou la détresse$x$, null, $x$Sunan Abī Dāwūd$x$, $x$1525$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Al-Albānī (jugement affiché sur sunnah.com)$x$, $x$https://sunnah.com/abudawud:1525$x$, $x$D'après Asmāʾ bint ʿUmays. Shuʿayb al-Arnaʾūṭ l'a aussi jugé authentique.$x$),
  (3, $x$C’est Ta miséricorde que j’espère$x$, $x$اللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ وَأَصْلِحْ لِي شَأْنِي كُلَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ$x$, $x$Allāhumma raḥmataka arjū, fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā ant.$x$, $x$« Ô Allah, c'est Ta miséricorde que j'espère ; ne me laisse pas à moi-même, ne serait-ce que le temps d'un clin d'œil, et améliore toutes mes affaires. Nul ne mérite d'être adoré si ce n'est Toi. »$x$, 1::smallint, $x$Dans l'angoisse ; le Prophète ﷺ les a appelées les invocations de celui qui est angoissé$x$, null, $x$Sunan Abī Dāwūd$x$, $x$5090$x$, $x$Chaîne bonne (ḥasan al-isnād)$x$, $x$Al-Albānī (jugement affiché sur sunnah.com)$x$, $x$https://sunnah.com/abudawud:5090$x$, $x$D'après Abū Bakra. Zubayr ʿAlī Zaʾī l'a jugé faible (jugements affichés sur sunnah.com).$x$),
  (4, $x$Quand un malheur frappe$x$, $x$إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا$x$, $x$Innā li-llāhi wa innā ilayhi rājiʿūn, allāhumma’jurnī fī muṣībatī wa akhlif lī khayran minhā.$x$, $x$« Nous appartenons à Allah et c'est vers Lui que nous retournerons. Ô Allah, récompense-moi pour mon malheur et remplace-le-moi par mieux. »$x$, 1::smallint, $x$Quand on est frappé par un malheur$x$, $x$Allah lui donne en échange mieux que ce qu'il a perdu. Umm Salama l'a dite à la mort de son mari Abū Salama, et Allah lui a donné le Prophète ﷺ pour époux.$x$, $x$Ṣaḥīḥ Muslim$x$, $x$918a$x$, $x$Authentique (ṣaḥīḥ)$x$, $x$Recueil authentique de Muslim$x$, $x$https://sunnah.com/muslim:918a$x$, $x$D'après Umm Salama.$x$)) v(k, title, arabic, transliteration, meaning, repeat_count, when_to_say, virtue, collection, hadith_number, grade, graded_by, url, note) order by v.k returning arabic)
select private.ai_log(rv.item_id, rv.id, 'created', null, null, $x$Brouillon rédigé par l'IA : invocations, L’angoisse et le malheur$x$),
       rv.id as revision, (select bool_and(md5(arabic) = any(array['c366016420890188073f39633dab9d33', '7eda176d467652f28ba5a0d27111f626', 'd1420aa2dce37ddb29ae9e0505efd4ae', 'a634169a7c667171d199d643e090de98'])) and count(*) = 4 from a) as arabe_ok,
       (select count(*) from r) as refs, (select count(*) from a) as adhkar from rv
